preConditionHook:
// EL Time is the bar's closing time as HHMM (EL_FEATURES.md `time`, ACCEPTED:
// exchange clock, no timezone conversion). ctx.Time(0) is that same close
// timestamp, so HHMM is just its seconds-of-day re-packed. A bar closing at
// midnight reads 0, as EL's Time does.
barSeconds = seconds_of_day(ctx.Time(0));
barHHMM = (barSeconds / 3600) * 100 + (barSeconds % 3600) / 60;
